import hou, math
g=hou.node('/obj/girl')
hc=hou.node('/obj/hand_contact'); hb=hou.node('/obj/girl/ctrl_rig_bone_hand_left')
headn=hou.node('/obj/girl/rig_bone_head')
base=hou.Vector3(0.0871763, 0.546539, 0.153165); bt=hou.Vector3(-0.31513106711217626, 0.004341544089813493, 0.1780316453785062)
def setw(p, r):
    d=p-base
    for i,a in enumerate('xyz'):
        g.parm('ikwristlefttranslate'+a).set(bt[i]+d[i]); g.parm('ikwristleftrotate'+a).set(r[i])
def st():
    m=hc.worldTransform(); R=m.extractRotationMatrix3()
    hm=hb.worldTransform(); HR=hm.extractRotationMatrix3()
    return m.extractTranslates(), hou.Vector3(0,1,0)*R, hm.extractTranslates(), hou.Vector3(0,0,-1)*HR
def headfwd(t=None):
    m=headn.worldTransform() if t is None else headn.worldTransformAtTime(t)
    return m.extractTranslates(), hou.Vector3(0,1,0)*m.extractRotationMatrix3(), hou.Vector3(1,0,0)*m.extractRotationMatrix3()

